import * as React from 'react';
import { expect, it, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);
const log = (label: string, v: unknown) => console.log(`[${process.env.VARIANT ?? 'head'}] ${label}:`, JSON.stringify(v));

it('P1 controlled onChange-mode renders per keystroke', () => {
  let renders = 0;
  const validate = vi.fn(() => null);
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root validationMode="onChange" validate={validate}>
        <Field.Control data-testid="c" value={value} onValueChange={setValue}
          render={(props) => { renders += 1; return <input {...props} />; }} />
      </Field.Root>
    );
  }
  render(<App />);
  const c = screen.getByTestId('c');
  fireEvent.change(c, { target: { value: 'a' } });
  const settled = renders;
  fireEvent.change(c, { target: { value: 'ab' } });
  fireEvent.change(c, { target: { value: 'abc' } });
  log('P1 renders for 2 keystrokes (onChange mode)', renders - settled);
});

it('P1b controlled default-mode invalid field renders per keystroke', () => {
  let renders = 0;
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Form errors={{ m: 'server' }}>
      <Field.Root name="m">
        <Field.Control data-testid="c" value={value} onValueChange={setValue}
          render={(props) => { renders += 1; return <input {...props} />; }} />
      </Field.Root>
      </Form>
    );
  }
  render(<App />);
  const c = screen.getByTestId('c');
  fireEvent.change(c, { target: { value: 'a' } });
  const settled = renders;
  fireEvent.change(c, { target: { value: 'ab' } });
  fireEvent.change(c, { target: { value: 'abc' } });
  log('P1b renders for 2 keystrokes (default mode, in Form)', renders - settled);
});

it('P2 controlled cancel', () => {
  const validate = vi.fn(() => null);
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value={value} onValueChange={(v, d) => { d.cancel(); setValue(v); }} />
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  log('P2 controlled cancel+setValue: validate calls', validate.mock.calls.length);
  log('P2 dirty', screen.getByTestId('root').hasAttribute('data-dirty'));
});

it('P3 uncontrolled cancel half-applied', () => {
  const validate = vi.fn(() => 'bad');
  render(
    <Form errors={{ m: 'Server error' }}>
      <Field.Root name="m" data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control onValueChange={(v, d) => d.cancel()} />
        <Field.Error data-testid="err" />
      </Field.Root>
    </Form>,
  );
  const c = screen.getByRole<HTMLInputElement>('textbox');
  fireEvent.change(c, { target: { value: 'a' } });
  const root = screen.getByTestId('root');
  log('P3 uncontrolled cancel', {
    domValue: c.value, dirty: root.hasAttribute('data-dirty'), filled: root.hasAttribute('data-filled'),
    validateCalls: validate.mock.calls.length, err: screen.queryByTestId('err')?.textContent ?? null,
  });
});

it('P4 disabled controlled programmatic change then enable', () => {
  const validate = vi.fn((v: unknown) => (v === 'loaded' ? 'bad' : null));
  function App() {
    const [value, setValue] = React.useState('');
    const [disabled, setDisabled] = React.useState(true);
    return (
      <Field.Root data-testid="root" disabled={disabled} validationMode="onChange" validate={validate}>
        <Field.Control value={value} onValueChange={setValue} />
        <Field.Error data-testid="err" />
        <button onClick={() => setValue('loaded')}>load</button>
        <button onClick={() => setDisabled(false)}>enable</button>
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByText('load'));
  const root = screen.getByTestId('root');
  log('P4 after load while disabled', { dirty: root.hasAttribute('data-dirty'), filled: root.hasAttribute('data-filled'), validateCalls: validate.mock.calls.length });
  fireEvent.click(screen.getByText('enable'));
  log('P4 after enable', { dirty: root.hasAttribute('data-dirty'), invalid: root.hasAttribute('data-invalid'), err: screen.queryByTestId('err')?.textContent ?? null });
