      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value={value} onValueChange={setValue} />
        <Field.Error data-testid="err" />
        <button onClick={() => setValue('from server')}>load</button>
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByText('load'));
  const root = screen.getByTestId('root');
  log('P5 hydration', { dirty: root.hasAttribute('data-dirty'), invalid: root.hasAttribute('data-invalid'), err: screen.queryByTestId('err')?.textContent ?? null });
});

